<?php

declare(strict_types=1);require_once __DIR__.'/../../includes/module-admin.php';$pdo=cmsAdminModuleBoot('audit');$q=cmsStr($_GET['q']??'',120);if($q!==''){$s=$pdo->prepare('SELECT a.*,u.name admin_name FROM audit_logs a LEFT JOIN admin_users u ON u.id=a.admin_user_id WHERE a.action_key LIKE :q OR a.entity_type LIKE :q OR a.details LIKE :q ORDER BY a.id DESC LIMIT 300');$s->execute([':q'=>'%'.$q.'%']);$rows=$s->fetchAll();}else{$rows=$pdo->query('SELECT a.*,u.name admin_name FROM audit_logs a LEFT JOIN admin_users u ON u.id=a.admin_user_id ORDER BY a.id DESC LIMIT 300')->fetchAll();}cmsAdminHead('سجل النشاط');cmsAdminSidebar('audit');cmsAdminTopbar('سجل النشاط');?>
<div class="content"><section class="card"><form class="toolbar" method="get"><label class="field"><span>بحث</span><input name="q" value="<?=cmsE($q)?>" placeholder="action / entity"></label><button class="btn primary">بحث</button></form><div class="table-wrap"><table class="table"><thead><tr><th>التاريخ</th><th>المدير</th><th>العملية</th><th>الكيان</th><th>التفاصيل</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=cmsE($r['created_at'])?></td><td><?=cmsE((string)($r['admin_name']??'System'))?></td><td><code><?=cmsE($r['action_key'])?></code></td><td><?=cmsE($r['entity_type'])?></td><td><?=cmsE((string)$r['details'])?></td></tr><?php endforeach;?></tbody></table></div></section></div><?php cmsAdminEnd();
